using System.Text; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Authorization; using Microsoft.IdentityModel.Tokens;
namespace JTradeERP.Api.Security;
public static class AuthenticationRegistration
{
 public static IServiceCollection AddJTradeErpAuthentication(this IServiceCollection services,IConfiguration configuration){var jwt=configuration.GetSection(JwtOptions.SectionName).Get<JwtOptions>()??throw new InvalidOperationException("Jwt configuration is required.");if(string.IsNullOrWhiteSpace(jwt.SigningKey)||Encoding.UTF8.GetByteCount(jwt.SigningKey)<32||string.IsNullOrWhiteSpace(jwt.Issuer)||string.IsNullOrWhiteSpace(jwt.Audience))throw new InvalidOperationException("Jwt issuer, audience and a signing key of at least 32 bytes must be configured through secrets or environment configuration.");services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.SigningKey)),ValidateIssuer=true,ValidIssuer=jwt.Issuer,ValidateAudience=true,ValidAudience=jwt.Audience,ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30),NameClaimType=System.Security.Claims.ClaimTypes.Name,RoleClaimType=System.Security.Claims.ClaimTypes.Role};});services.AddAuthorization(o=>o.FallbackPolicy=new AuthorizationPolicyBuilder().RequireAuthenticatedUser().Build());services.AddScoped<IAuthorizationHandler,PermissionAuthorizationHandler>();return services;}
}
